def reverseOddLevels(self, root):
    from collections import deque
    q = deque([root])
    level = 0
    while q:
        size = len(q)
        nodes = []
        for _ in range(size):
            node = q.popleft()
            nodes.append(node)
            if node.left:
                q.append(node.left)
                q.append(node.right)
        if level % 2 == 1:
            vals = [n.val for n in nodes]
            for i, n in enumerate(nodes):
                n.val = vals[~i]
        level += 1
    return root

