def numberOfGoodPaths(self, vals, edges):
    from collections import defaultdict
    n = len(vals)
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    val_to_nodes = defaultdict(list)
    for i, v in enumerate(vals):
        val_to_nodes[v].append(i)
    res = n
    for val in sorted(val_to_nodes):
        for node in val_to_nodes[val]:
            for nei in adj[node]:
                if vals[nei] <= val:
                    parent[find(nei)] = find(node)
        cnt = defaultdict(int)
        for node in val_to_nodes[val]:
            cnt[find(node)] += 1
        for c in cnt.values():
            res += c * (c - 1) // 2
    return res

def minimumOperations(self, nums):
    l, r = 0, len(nums) - 1
    left, right = nums[l], nums[r]
    ops = 0
    while l < r:
        if left == right:
            l += 1
            r -= 1
            if l < r:
                left, right = nums[l], nums[r]
        elif left < right:
            l += 1
            left += nums[l]
            ops += 1
        else:
            r -= 1
            right += nums[r]
            ops += 1
    return ops

