def treeQueries(self, root, queries):
    height = {}
    depth = {}
    level_max = {}
    def get_height(node):
        if not node:
            return -1
        h = 1 + max(get_height(node.left), get_height(node.right))
        height[node.val] = h
        return h
    def get_depth(node, d):
        if not node:
            return
        depth[node.val] = d
        h = height[node.val]
        if d not in level_max:
            level_max[d] = (h, -1)
        else:
            m1, m2 = level_max[d]
            if h >= m1:
                level_max[d] = (h, m1)
            elif h > m2:
                level_max[d] = (m1, h)
        get_depth(node.left, d + 1)
        get_depth(node.right, d + 1)
    get_height(root)
    get_depth(root, 0)
    ans = []
    for q in queries:
        d = depth[q]
        h = height[q]
        m1, m2 = level_max[d]
        other = m1 if h != m1 else m2
        ans.append(d + other if other >= 0 else d - 1)
    return ans

def sortArray(self, nums):
    n = len(nums)
    def count_ops(target):
        pos = {v: i for i, v in enumerate(nums)}
        visited = [False] * n
        ops = 0
        for i in range(n):
            if visited[i] or nums[i] == target[i]:
                continue
            cycle_len = 0
            has_zero = False
            j = i
            while not visited[j]:
                visited[j] = True
                if target[j] == 0:
                    has_zero = True
                j = pos[target[j]]
                cycle_len += 1
            ops += cycle_len - 1 if has_zero else cycle_len + 1
        return ops
    t1 = list(range(n))
    t2 = list(range(1, n)) + [0]
    return min(count_ops(t1), count_ops(t2))

def applyOperations(self, nums):
    n = len(nums)
    for i in range(n - 1):
        if nums[i] == nums[i + 1]:
            nums[i] *= 2
            nums[i + 1] = 0
    res = [x for x in nums if x != 0]
    res.extend([0] * (n - len(res)))
    return res
